    private static double N(Settings v,string key,double fallback=0)=>v.GetValueOrDefault(key,fallback).AsDouble();private static Vector3 V(Settings v,string key,Vector3 fallback)=>v.GetValueOrDefault(key,fallback).AsVector3();
    private static Resource Actor(RefCounted controller,string id)=>controller.Get("prototypes").AsGodotDictionary()[id].AsGodotDictionary()["actor"].As<Resource>();
