    private Resource? Resolve(Variant value){if(value.VariantType!=Variant.Type.Object||value.AsGodotObject() is not Resource resource)return null;return ActorDataOperations.ScriptIs(resource,"res://scripts/actors/core/actor_object_reference.gd")?_animation.resolve_reference(resource):ActorDataOperations.ScriptIs(resource,"res://scripts/actors/core/actor_object_data.gd")?resource:null;}
    public Settings values(RefCounted controller,string id,double time)=>_animation.sampled_values(Actor(controller,id),Local(controller,id,time));
    public double mask_value(Settings source,Vector3 unit,Vector3 world)=>source.Count==0?1:Math.Clamp(_field.sample_prepared(source,unit,world)*mask_value(source["mask"].AsGodotDictionary(),unit,world),0,1);
    public Transform3D source_pose(RefCounted controller,string id,Settings v,double time)
    {
        var actor=Actor(controller,id);string target=v.GetValueOrDefault("source_actor","").AsString();var links=actor.Get("values").AsGodotDictionary().GetValueOrDefault("fog_motion_links",new Settings()).AsGodotDictionary();target=links.GetValueOrDefault(target,target).AsString();var pose=target.Length>0?controller.Call("bone_world",target,v.GetValueOrDefault("source_bone","").AsString(),time).AsTransform3D():controller.Call("animated_world",id,time,true,new Settings()).AsTransform3D();pose.Origin=pose*V(v,"position",Vector3.Zero);return pose;
