    public void initialize(RefCounted controller,string id,Settings state,Settings config,double time)
    {
        var v=values(controller,id,time);var world=controller.Call("animated_world",id,time,true,new Settings()).AsTransform3D();var dimensions=(V(v,"volume_size",new Vector3(4,2,4)).Abs()*world.Basis.Scale.Abs()).Max(Vector3.One*.01f);var pose=new Transform3D(world.Basis.Orthonormalized(),world.Origin);int n=_definition.resolution(v);var rho=new float[n*n*n];
