        state.Merge(_solver.initialize(n,dimensions,rho),true);state["fog_pose"]=pose;state["fog_time"]=Local(controller,id,time);state["fog_source_previous"]=new Settings();state["fog_obstacle_previous"]=new Settings();obstacles(controller,id,state,v,0);emit_sources(controller,id,state,v,time,0);
    }
    public bool contains(Shape3D shape,Vector3 p,Vector3 padding)
    {
        if(shape is BoxShape3D box)return Math.Abs(p.X)<=box.Size.X*.5+padding.X&&Math.Abs(p.Y)<=box.Size.Y*.5+padding.Y&&Math.Abs(p.Z)<=box.Size.Z*.5+padding.Z;if(shape is SphereShape3D sphere)return p.Length()<=sphere.Radius+padding.Length()*.5;if(shape is CapsuleShape3D capsule){p.Y-=Math.Clamp(p.Y,-Math.Max(0,capsule.Height*.5f-capsule.Radius),Math.Max(0,capsule.Height*.5f-capsule.Radius));return p.Length()<=capsule.Radius+padding.Length()*.5;}if(shape is CylinderShape3D cylinder)return new Vector2(p.X,p.Z).Length()<=cylinder.Radius+Math.Max(padding.X,padding.Z)&&Math.Abs(p.Y)<=cylinder.Height*.5+padding.Y;if(shape is ConvexPolygonShape3D hull){var points=hull.Points;if(points.Length==0)return false;var aabb=new Aabb(points[0],Vector3.Zero);foreach(var point in points)aabb=aabb.Expand(point);return aabb.Grow(padding.Length()*.5f).HasPoint(p);}return false;
    }
    public Aabb bounds(Shape3D shape)
    {
        Vector3 size=shape switch{BoxShape3D box=>box.Size,SphereShape3D sphere=>Vector3.One*sphere.Radius*2,CapsuleShape3D capsule=>new Vector3(capsule.Radius*2,capsule.Height,capsule.Radius*2),CylinderShape3D cylinder=>new Vector3(cylinder.Radius*2,cylinder.Height,cylinder.Radius*2),_=>Vector3.Zero};if(shape is ConvexPolygonShape3D hull){var points=hull.Points;if(points.Length>0){var box=new Aabb(points[0],Vector3.Zero);foreach(var point in points)box=box.Expand(point);return box;}}return new Aabb(-size*.5f,size);
    }
    public void interpolate(Settings result,Settings left,Settings right,double fraction)
    {
        if(!left.ContainsKey("fog_density")||!right.ContainsKey("fog_density")||left["fog_n"].AsInt32()!=right["fog_n"].AsInt32())return;foreach(string key in new[]{"fog_density","fog_pressure"}){var a=left[key].AsFloat32Array();var b=right[key].AsFloat32Array();for(int i=0;i<a.Length;i++)a[i]=Mathf.Lerp(a[i],b[i],(float)fraction);result[key]=a;}var va=left["fog_velocity"].AsVector3Array();var vb=right["fog_velocity"].AsVector3Array();for(int i=0;i<va.Length;i++)va[i]=va[i].Lerp(vb[i],(float)fraction);result["fog_velocity"]=va;result["fog_solid"]=left["fog_solid"].AsByteArray();result["fog_pose"]=left["fog_pose"].AsTransform3D().InterpolateWith(right["fog_pose"].AsTransform3D(),(float)fraction);result["fog_time"]=Mathf.Lerp(left["fog_time"].AsDouble(),right["fog_time"].AsDouble(),fraction);
    }
    public void apply(RefCounted controller,string id,Settings state,double time){var runtime=controller.Call("_runtime",id).As<Node>();if(runtime==null)return;var result=_render.apply(runtime,state,values(controller,id,time));int n=state["fog_n"].AsInt32();runtime.SetMeta("fog_motion_stats",new Settings{["cpu_ms"]=state.GetValueOrDefault("fog_cpu_ms",0.0),["upload_ms"]=result["upload_ms"],["cells"]=n*n*n,["mass"]=_solver.total_mass(state),["lost"]=state["fog_lost"],["error"]=result["error"]});if(result["error"].AsString().Length>0)controller.Call("_warn",result["error"]);}
